    ADDI X1, X0, #1236
    ADDI X2, X0, #475
    BL draw2
    ADDI X1, X0, #1238
    STR X1, [X27, #4]
    BL mark_cell
    ADDI X1, X0, #1238
    ADDI X2, X0, #475
    BL draw2
    ADDI X1, X0, #1240
    STR X1, [X27, #8]
    BL mark_cell
    ADDI X1, X0, #1240
    ADDI X2, X0, #731
    BL draw2
    ADDI X15, X0, #1240
    ADDI X16, X0, #2
    ADDI X17, X0, #0
    ADDI X18, X0, #1
    ADDI X19, X0, #1
    ADDI X20, X0, #0
    ADDI X21, X0, #8
    LDR X1, [X26, #256]
    STR X1, [X27, #-32748]
    LDR X2, [X27, #-32756]
    EOR X2, X2, X1
    ORI X2, X2, #1
