    SUBI X31, X1, #81
    CBZ X31, sn_quit
    SUBI X31, X1, #27
    CBZ X31, sn_quit
    SUBI X31, X1, #119
    CBZ X31, sn_d0
    SUBI X31, X1, #87
    CBZ X31, sn_d0
    SUBI X31, X1, #129
    CBZ X31, sn_d0
    SUBI X31, X1, #100
    CBZ X31, sn_d1
    SUBI X31, X1, #68
    CBZ X31, sn_d1
    SUBI X31, X1, #132
    CBZ X31, sn_d1
    SUBI X31, X1, #115
    CBZ X31, sn_d2
    SUBI X31, X1, #83
    CBZ X31, sn_d2
    SUBI X31, X1, #130
    CBZ X31, sn_d2
    SUBI X31, X1, #97
    CBZ X31, sn_d3
    SUBI X31, X1, #65
    CBZ X31, sn_d3
    SUBI X31, X1, #131
    CBZ X31, sn_d3
    B sn_frame
sn_d0:
    ADDI X2, X0, #0
    EOR X3, X2, X18
    SUBI X31, X3, #2
    CBZ X31, sn_frame
    ADD X19, X2, X0
