    ADDI X2, X27, #-27264
    BL dec_to_buf
    ADDI X1, X0, #1245
    ADDI X2, X27, #-27264
    ADDI X3, X0, #0
    BL gfx_puts
    ADDI X1, X0, #1312
    ADDI X2, X27, #-30356
    ADDI X3, X0, #512
    BL gfx_puts
    LDR X21, [X26, #256]
sn_settle:
    BL pollkey
    LDR X1, [X26, #256]
    SUB X1, X1, X21
    SUBI X31, X1, #60
